  'src/i18n/locale/vn.ts',
  'src/i18n/locale/zh.ts',
  'src/i18n/locale/zh_tw.ts',
];
const rel = (f) => path.relative(root, f).split(path.sep).join('/');

function run(ref) {
  const overlay = new Map();
  if (ref) {
    for (const f of delta) {
      overlay.set(f, execFileSync('git', ['show', `${ref}:${f}`], { encoding: 'utf8', maxBuffer: 30 * 1024 * 1024 }));
    }
  }
  const host = ts.createCompilerHost(options, true);
  const readFile = host.readFile.bind(host);
  host.readFile = (fileName) => (overlay.has(rel(fileName)) ? overlay.get(rel(fileName)) : readFile(fileName));
  const program = ts.createProgram({ rootNames: parsed.fileNames, options, host });
  const want = new Set(delta);
  const out = [];
  const covered = new Set();
  for (const sf of program.getSourceFiles()) {
    const r = rel(sf.fileName);
    if (!want.has(r)) continue;
    covered.add(r);
    const diags = [...ts.getPreEmitDiagnostics(program, sf), ...program.getSuggestionDiagnostics(sf)];
    for (const d of diags) {
      const pos = d.file && typeof d.start === 'number' ? d.file.getLineAndCharacterOfPosition(d.start) : null;
      out.push({
        file: r,
        code: d.code,
        cat: ts.DiagnosticCategory[d.category],
        line: pos ? pos.line + 1 : null,
        msg: ts.flattenDiagnosticMessageText(d.messageText, '\n').split('\n')[0],
      });
    }
  }
  return { out, covered };
}

