  const a = countMap(from), b = countMap(to), res = [];
  for (const d of to) {
    const k = key(d);
    if ((b.get(k) || 0) > (a.get(k) || 0)) { res.push(d); b.set(k, b.get(k) - 1); }
  }
  return res;
}

